"""Add a navigation bar to the documentation pages of the website.

The pages in docs/ are generated by buildfile.m for MATLAB's help browser,
where links to the website would be out of place: the bar is only added
when the website is assembled (.github/workflows/release.yml).

Usage: python3 add_site_nav.py <site folder>
"""
import pathlib
import re
import sys

NAV = """<style>
/* Neutral colors, readable on light pages and on the cheat sheet in dark mode */
.gramm-site-nav { font:14px/1.4 -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
  background:rgba(128,128,128,0.08); border-bottom:1px solid rgba(128,128,128,0.25); }
.gramm-site-nav div { max-width:920px; margin:0 auto; padding:10px 24px; display:flex; flex-wrap:wrap; gap:6px 22px; align-items:baseline; }
.gramm-site-nav a, .gramm-site-nav a:visited { color:#3b7ddd; text-decoration:none; }
.gramm-site-nav a:hover { text-decoration:underline; }
.gramm-site-nav a.home, .gramm-site-nav a.home:visited { font-weight:600; font-size:16px; color:inherit; }
</style>
<nav class="gramm-site-nav"><div>
<a class="home" href="{root}index.html">gramm</a>
<a href="{root}docs/GettingStarted.html">Tutorials</a>
<a href="{root}docs/examples/index.html">Examples</a>
<a href="{root}docs/gramm_cheat_sheet.html">Cheat sheet</a>
<a href="https://github.com/piermorel/gramm">GitHub</a>
</div></nav>
"""

site = pathlib.Path(sys.argv[1])
for page in sorted((site / "docs").rglob("*.html")):
    html = page.read_text(encoding="utf-8")
    if "gramm-site-nav" in html:
        continue
    # Relative path to the site root, so that the links work wherever the
    # site is served from
    root = "../" * (len(page.relative_to(site).parts) - 1)
    html, n = re.subn(r"(<body[^>]*>)", lambda m: m.group(1) + "\n" + NAV.replace("{root}", root),
                      html, count=1, flags=re.IGNORECASE)
    if n:
        page.write_text(html, encoding="utf-8")
    else:
        print(f"No <body> in {page}, navigation bar not added")
